1	// "Never build an `AVAudioEngine` to ask whether a microphone exists" (#88), as
2	// a check: `AVAudioEngine` may only be constructed in `AudioHub`.
3	//
4	// Touching `engine.inputNode` — which `AudioHub.makeEngine()` must do, because
5	// `prepare()` asserts a node is attached (#72) — opens the default input device
6	// and mints a hidden per-client aggregate device inside coreaudiod
7	// (`CADefaultDeviceAggregate-<pid>-<n>`). So constructing an engine is never a
8	// cheap read: one measured outage ran that open/create/destroy cycle ~210 times
9	// over 3h40m against hardware that was not there at all. `AudioDiagnostics`
10	// exists so nothing else has to — it answers "is there a usable mic?" with
11	// `AudioObjectGetPropertyData` property queries that open nothing.
12	//
13	// A positive whitelist over the construction site, not a ban list on the callers
14	// that shouldn't do it: a new file that reaches for an engine is caught the day
15	// it lands, which enumerating today's innocent files could not do.
16	//
17	// Dependency-free by design (a local pack must load without the canon mount),
18	// so the finding object is built by hand rather than via the engine helper.
19	
20	// The one file allowed to build one. `AudioHub` owns the microphone, rebuilds the
21	// engine on every start (#61), and is where `makeEngine()` keeps the
22	// materialize-inputNode-before-prepare() rule in one place.
23	const OWNER = 'mac/Sources/LaughCounter/AudioHub.swift';
24	
25	// A construction, not a mention: `AVAudioEngine()` with arguments-or-not, but not
26	// `var engine: AVAudioEngine` and not `AVAudioEngineConfigurationChange`.
27	const CONSTRUCTION = /\bAVAudioEngine\s*\(/g;
28	
29	const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');
30	
31	const rule = {
32	  id: 'macos-audio/engine-construction-confined',
33	  severity: 'blocking',
34	  description: 'Only AudioHub builds an AVAudioEngine — nothing else opens the mic to ask a question (mac/Sources/)',
35	  doc: '.claudinite/local/packs/macos-audio/RULES.md',
36	  why: 'constructing an engine opens the default input and churns a hidden coreaudiod aggregate device — the one mechanism by which this app could plausibly wedge a mic',
37	
38	  run(ctx) {
39	    const out = [];
40	    for (const file of ctx.files.filter(inScope)) {
41	      if (file === OWNER) continue;
42	      const text = ctx.read(file);
43	      if (text === null) continue;
44	      CONSTRUCTION.lastIndex = 0;
45	      let m = CONSTRUCTION.exec(text);
46	      while (m !== null) {
47	        out.push({
48	          rule: rule.id,
49	          severity: rule.severity,
50	          file,
51	          line: text.slice(0, m.index).split('\n').length,
52	          what: `builds an AVAudioEngine outside ${OWNER} (${file})`,
53	          why: rule.why,
54	          fix: 'ask AudioDiagnostics instead — `hasUsableInput` / `inputAvailability` answer from HAL property queries that open no device; if capture really is needed, route it through AudioHub, which is the single owner of the engine lifecycle',
55	          doc: rule.doc,
56	        });
57	        m = CONSTRUCTION.exec(text);
58	      }
59	    }
60	    return out;
61	  },
62	};
63	
64	export default rule;
65

